from payhook.errors import InvalidNotification

MAX_TIMESTAMP_SKEW_SECONDS = 300
_SIGNATURE_PREFIX = "v1="


def _header(headers, name):
    """Return a header value by case-insensitive name, or None."""
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == name:
            return value
    return None


def _check_timestamp(headers, now):
    stamp = _header(headers, "x-pay-timestamp")
    if stamp is None:
        raise InvalidNotification("missing X-Pay-Timestamp")
    try:
        stamp_seconds = int(stamp, 10)
    except (TypeError, ValueError):
        raise InvalidNotification("malformed X-Pay-Timestamp")
    if abs(now - stamp_seconds) > MAX_TIMESTAMP_SKEW_SECONDS:
        raise InvalidNotification("stale X-Pay-Timestamp")
    return stamp


def _check_signature(headers, raw_body, secret, stamp):
    signature = _header(headers, "x-pay-signature")
    if signature is None or not signature.startswith(_SIGNATURE_PREFIX):
        raise InvalidNotification("missing or malformed X-Pay-Signature")
    received = signature[len(_SIGNATURE_PREFIX):]
    message = stamp.encode("ascii") + b"." + raw_body
    expected = hmac.new(secret, message, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(received, expected):
        raise InvalidNotification("X-Pay-Signature mismatch")


def _validate(event):
    if not isinstance(event, dict):
        raise InvalidNotification("notification is not a JSON object")
    event_id = event.get("event_id")
    account_id = event.get("account_id")
    amount_minor = event.get("amount_minor")
    currency = event.get("currency")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("invalid event_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("invalid account_id")
    if (isinstance(amount_minor, bool) or not isinstance(amount_minor, int)
            or amount_minor < 0):
        raise InvalidNotification("invalid amount_minor")
    if (not isinstance(currency, str) or len(currency) != 3
            or not currency.isascii() or not currency.isupper()
            or not currency.isalpha()):
        raise InvalidNotification("invalid currency")
    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    stamp = _check_timestamp(headers, now)
    _check_signature(headers, raw_body, secret, stamp)
    try:
        event = json.loads(raw_body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        raise InvalidNotification("malformed JSON body")
    return _validate(event)
